use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn public_api_retries_transient_failures_and_caps_delay() {
    let config = RetryConfig {
        max_attempts: 4,
        base_delay_ms: 7,
        max_delay_ms: 10,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        if calls < 4 {
            Err(RetryError::Transient("temporary".to_owned()))
        } else {
            Ok(())
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 4);
    assert_eq!(sleeper.sleeps, vec![7, 10, 10]);
}

#[test]
fn public_api_does_not_retry_permanent_failures() {
    let config = RetryConfig {
        max_attempts: 4,
        base_delay_ms: 7,
        max_delay_ms: 10,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("bad input".to_owned()))
    });

    assert_eq!(result, Err(RetryError::Permanent("bad input".to_owned())));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

